import { getCustomer } from './customers.js';
import { formatEuros } from './money.js';
import { invoiceTotals, lineTotal, lineDiscount } from './invoices.js';
import { balanceDue } from './payments.js';

/**
 * Render an invoice as plain text.
 * @param {{ customerId: string, issueDate: string, status: string, dueDate?: string, lines: Array, number?: string, voucher?: { code: string, amount: number }, payments?: Array }} invoice
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  const customerResult = getCustomer(invoice.customerId);
  const customerName = customerResult.ok ? customerResult.value.name : `Unknown Customer (${invoice.customerId})`;

  const invoiceNumber = invoice.number || 'DRAFT';
  const lines = [invoiceNumber, customerName];

  for (const line of invoice.lines) {
    const total = lineTotal(line);
    let itemLine = `${line.qty} × ${line.name} @ ${formatEuros(line.unitPrice)} = ${formatEuros(total)}`;

    if (line.discountPercent) {
      const discount = lineDiscount(line);
      const finalTotal = Math.max(0, total - discount);
      itemLine += ` - ${line.discountPercent}% (${formatEuros(discount)}) = ${formatEuros(finalTotal)}`;
    }

    lines.push(itemLine);
  }

  const totals = invoiceTotals(invoice);
  if (totals.discount > 0) {
    lines.push(`Subtotal: ${formatEuros(totals.subtotal)}`);
    lines.push(`Discount: -${formatEuros(totals.discount)}`);
  }
  if (totals.vat > 0) {
    lines.push(`VAT: ${formatEuros(totals.vat)}`);
  }

  if (invoice.voucher) {
    lines.push(`Voucher (${invoice.voucher.code}): -${formatEuros(invoice.voucher.amount)}`);
  }

  lines.push(`Total: ${formatEuros(totals.total)}`);

  if (invoice.dueDate) {
    lines.push(`Due: ${invoice.dueDate}`);
  }

  if (invoice.payments && invoice.payments.length > 0) {
    const totalPaid = invoice.payments.reduce((sum, p) => sum + p.amount, 0);
    lines.push(`Paid: ${formatEuros(totalPaid)}`);
  }

  return lines.join('\n');
}

