  }).value;

  const text = renderInvoiceText(invoice);

  // 10 × 2,450.00 = 24,500.00
  assert.match(text, /€2,450\.00/);
  assert.match(text, /€24,500\.00/);
});

test('renderInvoiceText produces multiline plain text', () => {
  const invoice = createInvoice({
    customerId: 'C-002', // standard tier, no discount
    issueDate: '2024-06-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 8 },
      { sku: 'DES-HOUR', qty: 3 },
    ],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.equal(lines.length, 6); // invoice# + customer + 2 items + VAT + total
  assert.equal(typeof text, 'string');
  assert.ok(text.includes('\n'));
});

test('renderInvoiceText shows discount on lines with discountPercent', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  // Should show: qty × name @ price = total - discount% (discount amount) = final total
  assert.match(lines[2], /10 × Development \(hour\) @ €95\.00 = €950\.00 - 10% \(€95\.00\) = €855\.00/);
});

test('renderInvoiceText shows subtotal and discount when applicable', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5, discountPercent: 20 },
      { sku: 'DES-HOUR', qty: 5, discountPercent: 10 },
    ],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  // Should include subtotal and discount lines
  assert.ok(lines.some((l) => l.startsWith('Subtotal:')));
  assert.ok(lines.some((l) => l.startsWith('Discount:')));
  assert.ok(lines.some((l) => l.startsWith('Total:')));
});

test('renderInvoiceText does not show subtotal when no discount', () => {
  const invoice = createInvoice({
    customerId: 'C-002', // standard tier, 0% discount
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  // Should have invoice#, customer, item, VAT, total (5 lines) - no subtotal/discount lines
  assert.equal(lines.length, 5);
  assert.ok(!lines.some((l) => l.startsWith('Subtotal:')));
  assert.ok(!lines.some((l) => l.startsWith('Discount:')));
  assert.ok(lines.some((l) => l.startsWith('VAT:')));
});

test('renderInvoiceText with decimal discount percentage', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 12.5 }],
  }).value;

  const text = renderInvoiceText(invoice);

  // 10 × 9500 = 95000, 12.5% = 11875, final = 83125 = €831.25
  assert.match(text, /12\.5%/);
  assert.match(text, /€831\.25/);
});

test('renderInvoiceText shows VAT line', () => {
  const invoice = createInvoice({
    customerId: 'C-002', // standard tier, no discount
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.ok(lines.some((l) => l.startsWith('VAT:')));
  assert.ok(lines.some((l) => l.startsWith('Total:')));
});

test('renderInvoiceText calculates correct VAT', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const text = renderInvoiceText(invoice);

  // 10 × 9500 = 95000, 21% VAT = 19950 = €199.50
  assert.match(text, /VAT: €199\.50/);
  // Total = 95000 + 19950 = 114950 = €1,149.50
  assert.match(text, /Total: €1,149\.50/);
});

test('renderInvoiceText shows VAT breakdown with discount', () => {
  const invoice = createInvoice({
    customerId: 'C-001', // gold tier, 5% discount
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.ok(lines.some((l) => l.startsWith('Subtotal:')));
  assert.ok(lines.some((l) => l.startsWith('Discount:')));
  assert.ok(lines.some((l) => l.startsWith('VAT:')));
  assert.ok(lines.some((l) => l.startsWith('Total:')));
});

test('renderInvoiceText with mixed VAT rates', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 }, // 21% VAT
      { sku: 'PRINT-A4', qty: 500 }, // 9% VAT
    ],
  }).value;

  const text = renderInvoiceText(invoice);

  // Line 1: 95000 @ 21% = 19950
  // Line 2: 18500 @ 9% = 1665
  // Total VAT = 21615 = €216.15
  assert.match(text, /VAT: €216\.15/);
});

test('renderInvoiceText does not show VAT if all lines exempt', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }], // 0% VAT
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.ok(!lines.some((l) => l.startsWith('VAT:')));
  assert.ok(lines.some((l) => l.startsWith('Total:')));
});

test('renderInvoiceText shows voucher before total', () => {
  let invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  }).value;

  invoice = applyVoucher(invoice, { code: 'SUMMER20', amount: 1000 }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  const voucherLineIndex = lines.findIndex((l) => l.startsWith('Voucher'));
  const totalLineIndex = lines.findIndex((l) => l.startsWith('Total:'));

  assert.ok(voucherLineIndex >= 0, 'should have voucher line');
  assert.ok(totalLineIndex > voucherLineIndex, 'voucher should come before total');
  assert.match(lines[voucherLineIndex], /Voucher \(SUMMER20\): -€10\.00/);
});

test('renderInvoiceText does not show voucher when none applied', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  }).value;

  const text = renderInvoiceText(invoice);
  assert.ok(!text.includes('Voucher'));
});

test('renderInvoiceText shows due date when present', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    terms: 'NET14',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  }).value;

  const text = renderInvoiceText(invoice);
  assert.match(text, /Due: 2024-01-29/);
});

test('renderInvoiceText does not show due date when not present', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [{ sku: 'DEV-HOUR', name: 'Development (hour)', qty: 1, unitPrice: 9500, vatRate: 21 }],
  };

  const text = renderInvoiceText(invoice);
  assert.ok(!text.includes('Due:'));
});

test('renderInvoiceText shows paid amount when payments exist', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'partially_paid',
    lines: [{ sku: 'DEV-HOUR', name: 'Development (hour)', qty: 1, unitPrice: 9500, vatRate: 21 }],
    payments: [
      { date: '2024-01-20', amount: 5000 },
      { date: '2024-01-25', amount: 3000 },
    ],
  };

  const text = renderInvoiceText(invoice);
  assert.match(text, /Paid: €80\.00/);
});

test('renderInvoiceText does not show paid when no payments', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'issued',
    lines: [{ sku: 'DEV-HOUR', name: 'Development (hour)', qty: 1, unitPrice: 9500, vatRate: 21 }],
  };

  const text = renderInvoiceText(invoice);
  assert.ok(!text.includes('Paid:'));
});

test('renderInvoiceText with voucher, due date, and payments', () => {
  let invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    terms: 'NET14',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  }).value;

  invoice = applyVoucher(invoice, { code: 'SAVE50', amount: 2000 }).value;
  invoice = { ...invoice, status: 'partially_paid', payments: [{ date: '2024-01-20', amount: 4000 }] };

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.ok(lines.some((l) => l.startsWith('Voucher')));
  assert.ok(lines.some((l) => l.startsWith('Due:')));
  assert.ok(lines.some((l) => l.startsWith('Paid:')));
