import test from 'node:test';
import assert from 'node:assert/strict';
import { renderInvoiceText } from '../src/render.js';
import { createInvoice, issueInvoice, applyVoucher } from '../src/invoices.js';

test('renderInvoiceText shows DRAFT for unsent invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.equal(lines[0], 'DRAFT');
});

test('renderInvoiceText shows invoice number when issued', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const text = renderInvoiceText(issued);
  const lines = text.split('\n');

  assert.equal(lines[0], 'INV-2024-0001');
});

test('renderInvoiceText includes customer name', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.equal(lines[1], 'Northwind Studio');
});

test('renderInvoiceText shows customer name for different customers', () => {
  const invoice1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  }).value;

  const invoice2 = createInvoice({
    customerId: 'C-010',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  }).value;

  assert.equal(renderInvoiceText(invoice1).split('\n')[1], 'Kite & Co');
  assert.equal(renderInvoiceText(invoice2).split('\n')[1], 'Tidewater Museum');
});

test('renderInvoiceText includes line details', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.match(lines[2], /10 × Development \(hour\)/);
  assert.match(lines[2], /€95\.00/);
  assert.match(lines[2], /€950\.00/);
});

test('renderInvoiceText shows all line items', () => {
  const invoice = createInvoice({
    customerId: 'C-002', // standard tier, no discount
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'ICON-SET', qty: 100 },
    ],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  // invoice# + customer + 3 items (bulk discount on all) + subtotal + discount + VAT + total + due date = 10
  assert.equal(lines.length, 10);
  assert.match(lines[2], /Development \(hour\)/);
  assert.match(lines[3], /Design work \(hour\)/);
  assert.match(lines[4], /Icon set \(24 icons\)/);
});

test('renderInvoiceText calculates line totals correctly', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'PRINT-A4', qty: 500 },
      { sku: 'LOGO-PACK', qty: 2 },
    ],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  // 500 × €0.37 = €185.00
  assert.match(lines[2], /500 × Printed flyer A4 \(each\) @ €0\.37 = €185\.00/);
  // 2 × €1,200.00 = €2,400.00
  assert.match(lines[3], /2 × Logo package @ €1,200\.00 = €2,400\.00/);
});

test('renderInvoiceText shows correct total', () => {
  const invoice = createInvoice({
    customerId: 'C-002', // standard tier, no discount
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'DES-HOUR', qty: 5 },
    ],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  // Subtotal: 137500 (9500 + 42500)
  // VAT: 28875 (21%)
  // Total = 137500 + 28875 = 166375 = €1,663.75
  assert.match(text, /Total: €1,663\.75/);
  assert.match(lines[lines.length - 1], /Due:/); // Last line should be due date
});

test('renderInvoiceText handles unknown customer', () => {
  const invoice = {
    customerId: 'C-999',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [{ sku: 'DEV-HOUR', qty: 1, name: 'Development (hour)', unitPrice: 9500, vatRate: 21 }],
  };

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.match(lines[1], /Unknown Customer \(C-999\)/);
});

test('renderInvoiceText formats currency with thousands separator', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'BRAND-BOOK', qty: 10 }],
  }).value;

  const text = renderInvoiceText(invoice);

  // 10 × 2,450.00 = 24,500.00
  assert.match(text, /€2,450\.00/);
  assert.match(text, /€24,500\.00/);
});

test('renderInvoiceText produces multiline plain text', () => {
  const invoice = createInvoice({
    customerId: 'C-002', // standard tier, no discount
    issueDate: '2024-06-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 8 },
      { sku: 'DES-HOUR', qty: 3 },
    ],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.equal(lines.length, 7); // invoice# + customer + 2 items + VAT + total + due date
  assert.equal(typeof text, 'string');
  assert.ok(text.includes('\n'));
});

test('renderInvoiceText shows discount on lines with discountPercent', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  // Should show: qty × name @ price = total - discount% (discount amount) = final total
  assert.match(lines[2], /10 × Development \(hour\) @ €95\.00 = €950\.00 - 10% \(€95\.00\) = €855\.00/);
});

test('renderInvoiceText shows subtotal and discount when applicable', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5, discountPercent: 20 },
      { sku: 'DES-HOUR', qty: 5, discountPercent: 10 },
    ],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  // Should include subtotal and discount lines
  assert.ok(lines.some((l) => l.startsWith('Subtotal:')));
  assert.ok(lines.some((l) => l.startsWith('Discount:')));
  assert.ok(lines.some((l) => l.startsWith('Total:')));
});

test('renderInvoiceText does not show subtotal when no discount', () => {
  const invoice = createInvoice({
    customerId: 'C-002', // standard tier, 0% discount
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  // Should have invoice#, customer, item, VAT, total (5 lines) - no subtotal/discount lines
  assert.equal(lines.length, 5);
  assert.ok(!lines.some((l) => l.startsWith('Subtotal:')));
  assert.ok(!lines.some((l) => l.startsWith('Discount:')));
  assert.ok(lines.some((l) => l.startsWith('VAT:')));
});

test('renderInvoiceText with decimal discount percentage', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 12.5 }],
  }).value;

  const text = renderInvoiceText(invoice);

  // 10 × 9500 = 95000, 12.5% = 11875, final = 83125 = €831.25
  assert.match(text, /12\.5%/);
  assert.match(text, /€831\.25/);
});

test('renderInvoiceText shows VAT line', () => {
  const invoice = createInvoice({
    customerId: 'C-002', // standard tier, no discount
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.ok(lines.some((l) => l.startsWith('VAT:')));
  assert.ok(lines.some((l) => l.startsWith('Total:')));
});

test('renderInvoiceText calculates correct VAT', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const text = renderInvoiceText(invoice);

  // 10 × 9500 = 95000, 21% VAT = 19950 = €199.50
  assert.match(text, /VAT: €199\.50/);
  // Total = 95000 + 19950 = 114950 = €1,149.50
  assert.match(text, /Total: €1,149\.50/);
